def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) == 0:
                return stack.pop

from typing import List

def all_prefixes(string: str) -> List[str]:
    """ Return list of all prefixes from shortest to longest of the input string
    >>> all_prefixes('abc')
    ['a', 'ab', 'abc']
    """
    prefixes = []
    for char in string:
        if char.islower():
            prefixes.append(char)
        elif char.isupper():
            prefixes.append(char)
        else:
            prefixes.append(char)
    return prefixes

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    return int(math.sqrt(n))

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    return string.upper().lower()

def incr_list(l: list) -> list:
    """Return list with elements incremented by 1."""
    return [i + 1 for i in l]

def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])

def fib(n: int) -> int:
    """Return n-th Fibonacci number.
    >>> fib(10)
    55
    >>> fib(1)
    1
    >>> fib(8)
    21
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fib(n-1) + fib(n-2)

def largest_prime_factor(n: int) -> int:
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    if n < 2:
        return 0
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits right by shift and return the result as a string.
    If shift > number of digits, return digits reversed.
    >>> circular_shift(12, 1)
    "21"
    >>> circular_shift(12, 2)
    "12"
    """
    if shift > 0:
        return ''.join([str(int(digit) % shift) for digit in str(x)])
    else:
        return ''.join([str(x) % shift for x in range(shift)])

def search(lst):
    """
    Returns the greatest integer that is greater than zero and has a frequency greater than or equal to the value of the integer itself.
    If no such a value exist, returns -1.
    """
    if not lst:
        return -1
    frequency = {}
    for num in lst:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1
    return max(frequency, key=frequency.get)

def triangle_area(a, b, c):
    """
    Given the lengths of the three sides of a triangle. Return the area of
    the triangle rounded to 2 decimal points if the three sides form a valid triangle.
    Otherwise return -1
    Three sides make a valid triangle when the sum of any two sides is greater 
    than the third side.
    """
    if a + b > c and a + c > b and b + c > a:
        return round(a, 2)
    else:
        return -1

def smallest_change(arr):
    """
    Given an array arr of integers, find the minimum number of elements that need to be changed to make the array palindromic.
    A palindromic array is an array that is read the same backwards and forwards. In one change, you can change one element to any other element.
    """
    palindromic_count = 0
    for i in range(len(arr)):
        if arr[i] == arr[i - 1]:
            palindromic_count += 1
        else:
            palindromic_count += 1
    return palindromic_count

def is_multiply_prime(a):
    """Return True if the given number is the multiplication of 3 prime numbers, False otherwise."""
    if a < 100:
        return False
    for i in range(2, int(a ** 0.5) + 1):
        if a % i == 0:
            return False
    return True

def is_simple_power(x, n):
    """Return true if n**int=x and false otherwise."""
    return n**int == x

def decimal_to_binary(decimal):
    """Convert a decimal number to binary format."""
    return bin(decimal)[2:]

